// Des: Tests AEAD: round trip, wrong key, tamper, key file
// Flo: seal then open > assert
// I/O: bytes > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const cryp = @import("ut-cryp-aead.zig");
fn arenNewz() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(std.testing.allocator); }
test "round trip, empty text, and the same text seals to different bytes each time" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); var keyz: [32]u8 = undefined; std.testing.io.random(&keyz); const onez = try cryp.sealPack(allo, std.testing.io, keyz, "tên, 0966353678, địa chỉ", "cont"); const twoz = try cryp.sealPack(allo, std.testing.io, keyz, "tên, 0966353678, địa chỉ", "cont"); try std.testing.expect(!std.mem.eql(u8, onez, twoz)); try std.testing.expect(std.mem.indexOf(u8, onez, "0966353678") == null); try std.testing.expectEqualStrings("tên, 0966353678, địa chỉ", try cryp.sealOpen(allo, keyz, onez, "cont")); const empz = try cryp.sealPack(allo, std.testing.io, keyz, "", ""); try std.testing.expectEqual(@as(usize, 0), (try cryp.sealOpen(allo, keyz, empz, "")).len); }
test "wrong key, wrong associated text, a changed byte and a short blob are all refused" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); var keyz: [32]u8 = undefined; std.testing.io.random(&keyz); var kez2 = keyz; kez2[0] ^= 1; const blob = try cryp.sealPack(allo, std.testing.io, keyz, "secret rows", "cont"); try std.testing.expectError(error.BadSeal, cryp.sealOpen(allo, kez2, blob, "cont")); try std.testing.expectError(error.BadSeal, cryp.sealOpen(allo, keyz, blob, "other")); const badz = try allo.dupe(u8, blob); badz[badz.len - 20] ^= 0x40; try std.testing.expectError(error.BadSeal, cryp.sealOpen(allo, keyz, badz, "cont")); for ([_]usize{ 0, 5, 20, 47 }) |lenz| try std.testing.expectError(error.BadSeal, cryp.sealOpen(allo, keyz, blob[0..lenz], "cont")); const nomg = try allo.dupe(u8, blob); nomg[0] = 'X'; try std.testing.expectError(error.BadSeal, cryp.sealOpen(allo, keyz, nomg, "cont")); }
test "key file: made once as 64 hex chars, loaded back identical, a damaged file is refused" { var aren = arenNewz(); defer aren.deinit(); const allo = aren.allocator(); var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const path = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}/keys/cont.key", .{tmpz.sub_path}); const onez = try cryp.keyzLoad(allo, std.testing.io, path); const twoz = try cryp.keyzLoad(allo, std.testing.io, path); try std.testing.expectEqualSlices(u8, &onez, &twoz); const text = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, path, allo, .limited(256)); try std.testing.expectEqual(@as(usize, 65), text.len); var filz = try std.Io.Dir.cwd().createFile(std.testing.io, path, .{}); try filz.writeStreamingAll(std.testing.io, "not a key"); filz.close(std.testing.io); try std.testing.expectError(error.BadSeal, cryp.keyzLoad(allo, std.testing.io, path)); }
